const cookie=name=>document.cookie.split('; ').find(x=>x.startsWith(name+'='))?.split('=').slice(1).join('=');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>{const shapes={status:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/>',key:'<path d="M14 7a5 5 0 1 0 3 9l4-4-3-3-2 2-2-2"/>',activity:'<path d="M4 13h4l2-5 4 9 2-5h4"/>',transfer:'<path d="m8 7 4-4 4 4M12 3v14m4 0-4 4-4-4"/>',check:'<path d="m6 12 4 4 8-9"/>',plus:'<path d="M12 5v14M5 12h14"/>',manage:'<path d="M5 7h14M8 12h8M10 17h4"/>',refresh:'<path d="M20 7v5h-5M19 12a7 7 0 1 0-2 5"/>'};return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||''}</svg>`};
const state={view:'dashboard',me:null,users:[],mieruUsers:[],mieruService:{ready:false,revision:''},naiveUsers:[],naiveService:{ready:false,host:''},fleet:[],admins:[],audit:[],filter:'all',query:'',naiveFilter:'all',naiveQuery:''};
let navigationGeneration=0;
let naiveConfigText='',naiveConfigUrl='';

function validServer(value){if(/^[A-Za-z0-9.-]{1,253}$/.test(value))return true;if(!/^[0-9A-Fa-f:.]+$/.test(value)||!value.includes(':'))return false;try{new URL(`http://[${value}]/`);return true}catch{return false}}
function proxyLink(value){
  try{const url=new URL(value);const allowed=(url.protocol==='tg:'&&url.hostname==='proxy'&&(url.pathname===''||url.pathname==='/'))||(url.protocol==='https:'&&['t.me','telegram.me'].includes(url.hostname)&&url.pathname==='/proxy');const keys=[...url.searchParams.keys()];const server=url.searchParams.getAll('server'),port=url.searchParams.getAll('port'),secret=url.searchParams.getAll('secret');if(!allowed||url.hash||keys.length!==3||new Set(keys).size!==3||server.length!==1||port.length!==1||secret.length!==1||!validServer(server[0])||!/^[0-9]{1,5}$/.test(port[0])||Number(port[0])<1||Number(port[0])>65535||!/^[0-9A-Fa-f]{32,512}$/.test(secret[0]))throw new Error();return value}catch{throw new Error('Сервис вернул некорректную ссылку подключения')}}
function qrSource(value){if(typeof value!=='string'||value.length>500000||!/^data:image\/svg\+xml;base64,[A-Za-z0-9+/=]+$/.test(value))throw new Error('Сервис вернул некорректный QR-код');return value}
function naiveProxyUrl(value,username){try{const url=new URL(value);if(url.protocol!=='https:'||url.hostname!==state.naiveService.host||!url.password||decodeURIComponent(url.username)!==username||(!['','443'].includes(url.port))||!['','/'].includes(url.pathname)||url.search||url.hash)throw new Error();return value}catch{throw new Error('Сервис вернул некорректную NaiveProxy-конфигурацию')}}

async function api(url,options={}){
  options.headers={...options.headers,'X-CSRF-Token':cookie('panel_csrf')||''};
  if(options.body&&!options.headers['content-type']) options.headers['content-type']='application/json';
  const response=await fetch(url,options);
  if(response.status===401){location='/login';throw new Error('Сессия завершена')}
  if(!response.ok){let detail='Не удалось выполнить действие';try{detail=(await response.json()).detail||detail}catch{}throw new Error(detail)}
  return response.status===204?null:response.json();
}

const loginForm=document.querySelector('#login');
if(loginForm) loginForm.addEventListener('submit',async event=>{
  event.preventDefault();
  const button=loginForm.querySelector('button');
  const error=document.querySelector('#error');
  error.textContent='';
  try{
    setBusy(button,true,'Входим…');
    await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(loginForm)))});
    location='/';
  }catch(exception){
    error.textContent=exception.message;
    setBusy(button,false);
  }
});

const view=document.querySelector('#view');
const titles={dashboard:['Обзор','Состояние всех прокси-протоколов в одном месте'],mieru:['Mieru','Пользователи, rolling-квоты и application-byte трафик'],users:['MTProxy','Пользователи, ссылки и ключи доступа'],naive:['NaiveProxy','HTTPS-прокси, конфигурации и доступы'],fleet:['Узлы','Реестр флота и подготовленные команды'],admins:['Администраторы','Роли и доступ к панели'],audit:['Журнал действий','Изменения, входы и операции с ключами']};
const roleNames={owner:'Владелец',admin:'Администратор',viewer:'Наблюдатель'};
const actionNames={'auth.login':'Вход в панель','auth.logout':'Выход','user.create':'Создан доступ','user.access':'Открыта ссылка','user.enable':'Доступ включён','user.disable':'Доступ заблокирован','user.rotate':'Ключ обновлён','user.delete':'Доступ удалён','naive.create':'Создан Naive-доступ','naive.access':'Открыта Naive-конфигурация','naive.enable':'Naive-доступ включён','naive.disable':'Naive-доступ отключён','naive.rotate':'Naive-пароль обновлён','naive.delete':'Naive-доступ удалён','naive.traffic.reset':'Сброшен Naive-счётчик','fleet.node.create':'Добавлен узел','admin.create':'Создан администратор','admin.update':'Изменён администратор','admin.delete':'Удалён администратор'};

function toast(message,type='ok'){
  const node=document.createElement('div');node.className='toast '+(type==='error'?'error':'');node.textContent=message;
  document.querySelector('#toast-region').append(node);setTimeout(()=>node.remove(),3200);
}
function setBusy(button,busy,label='Подождите…'){if(!button)return;if(busy){button.dataset.label=button.textContent;button.textContent=label;button.disabled=true}else{button.textContent=button.dataset.label||button.textContent;button.disabled=false}}
function initials(name){return String(name||'?').slice(0,2).toUpperCase()}
function number(value){return new Intl.NumberFormat('ru-RU').format(Number(value)||0)}
function bytes(value){let n;try{n=BigInt(String(value??0));if(n<0n)throw new Error()}catch{return '0 Б'}const units=['Б','КБ','МБ','ГБ','ТБ','ПБ'];let index=0,scale=1n;while(index<units.length-1&&n>=scale*1024n){scale*=1024n;index++}if(index===0)return `${n} ${units[index]}`;const tenths=(n*10n+scale/2n)/scale;return `${tenths<100n?`${tenths/10n}.${tenths%10n}`:(n+scale/2n)/scale} ${units[index]}`}
function sumNaiveTraffic(users){return users.reduce((sum,user)=>sum+BigInt(String(user.total_bytes_decimal??'0')),0n)}
function date(value){if(!value)return '—';const n=Number(value);const d=new Date(n?(n<1e12?n*1000:n):value);return Number.isNaN(d.valueOf())?'—':d.toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function skeleton(){view.innerHTML='<div class="skeleton-grid"><i></i><i></i><i></i><i></i></div>'}
function errorState(error){view.innerHTML=`<div class="empty-state"><span>!</span><h3>Не удалось загрузить данные</h3><p>${esc(error.message)}</p><button class="secondary" data-action="retry">Повторить</button></div>`}

async function navigate(name){
  const generation=++navigationGeneration;state.view=name;const [title,subtitle]=titles[name];document.querySelector('#title').textContent=title;document.querySelector('#subtitle').textContent=subtitle;
  document.querySelectorAll('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===name));
  const canCreate=(state.me?.role!=='viewer'&&(name==='users'||name==='naive'||name==='mieru'))||(name==='fleet'&&state.me?.role==='owner')||(name==='admins'&&state.me?.role==='owner');
  const add=document.querySelector('#add');add.hidden=!canCreate;document.querySelector('#add-label').textContent=name==='admins'?'Администратора':name==='fleet'?'Узел':name==='naive'?'Naive доступ':name==='mieru'?'Mieru доступ':'Подключение';
  skeleton();try{if(name==='dashboard')await renderDashboard(generation);if(name==='users')await renderUsers(generation);if(name==='mieru')await renderMieru(generation);if(name==='naive')await renderNaive(generation);if(name==='fleet')await renderFleet(generation);if(name==='admins')await renderAdmins(generation);if(name==='audit')await renderAudit(generation)}catch(error){if(generation===navigationGeneration&&state.view===name)errorState(error)}
}

async function refreshUsers(generation=null){const data=await api('/api/users');if(generation!==null&&generation!==navigationGeneration)return null;state.users=data.items||[];document.querySelector('#users-count').textContent=state.users.length;return state.users}
async function renderDashboard(generation=navigationGeneration){
  const [data,users]=await Promise.all([api('/api/dashboard'),refreshUsers(generation)]);
  if(generation!==navigationGeneration||state.view!=='dashboard'||users===null)return;
  const mt=data.protocols?.mtproxy||{},naive=data.protocols?.naive||{available:false,status:'disabled'},mieru=data.protocols?.mieru||{available:false,status:'disabled'},mtReady=mt.ready===true,naiveReady=naive.ready===true,naiveAvailable=naive.available===true,mieruReady=mieru.ready===true,mieruAvailable=mieru.available===true,allReady=mtReady&&(!naiveAvailable||naiveReady)&&(!mieruAvailable||mieruReady);
  const system=document.querySelector('.system-mini');system.classList.toggle('degraded',!allReady);system.querySelector('b').textContent=allReady?'Прокси-сервисы работают':'Есть неполадки';system.querySelector('small').textContent=allReady?'Сводка актуальна':'Откройте обзор состояния';
  const mtCred=mt.credentials||{},naiveCred=naive.credentials||{};
  const naiveState=!naiveAvailable?'Функция отключена':naiveReady?'Manager работает':'NaiveProxy недоступен';
  const naiveStatus=!naiveAvailable?'Отключён':naiveReady?'Работает':'Сбой manager';
  const naiveAccess=naiveCred.available===false?'Данные недоступны':`${number(naiveCred.active)} активных · ${number(naiveCred.disabled)} отключённых`;
  view.innerHTML=`<div class="protocol-overview">
    <article class="protocol-card ${mtReady?'':'degraded'}"><div class="protocol-head"><span><small>MTProto · FakeTLS</small><h2>MTProxy</h2></span><span class="status-pill ${mtReady?'active':'blocked'}"><i></i>${mtReady?'Работает':'Недоступен'}</span></div><div class="protocol-access"><span><small>Активные доступы</small><strong>${number(mtCred.active)}</strong></span><span><small>Отключённые</small><strong>${number(mtCred.disabled)}</strong></span></div><div class="protocol-metrics"><span><small>Соединения сейчас</small><b>${number(mt.runtime?.current_connections)}</b></span><span><small>Активные IP</small><b>${number(mt.runtime?.active_ips)}</b></span><span><small>Runtime-трафик</small><b>${bytes(mt.runtime?.traffic_octets)}</b><em>Для текущего runtime-поколения; не квота</em></span></div></article>
    <article class="protocol-card ${mieruReady?'':'degraded'}"><div class="protocol-head"><span><small>Native AEAD · TCP/UDP</small><h2>Mieru</h2></span><span class="status-pill ${mieruReady?'active':'blocked'}"><i></i>${!mieruAvailable?'Отключён':mieruReady?'Работает':'Недоступен'}</span></div><div class="protocol-access"><span><small>Активные доступы</small><strong>${number(mieru.credentials?.active)}</strong></span><span><small>Отключённые</small><strong>${number(mieru.credentials?.disabled)}</strong></span></div><div class="protocol-metrics"><span><small>Application bytes</small><b>${mieru.traffic?.available?bytes(mieru.traffic?.bytes):'—'}</b><em>rolling admission quota (approximate), не hard cap</em></span></div><button class="quick-action" data-quick="mieru-users"><span>${icon('manage')}</span><span><b>Открыть Mieru</b></span></button></article>
    <article class="protocol-card naive-card ${naiveReady?'':'degraded'}"><div class="protocol-head"><span><small>HTTPS · HTTP/2 CONNECT</small><h2>NaiveProxy</h2></span><span class="status-pill ${naiveReady?'active':'blocked'}"><i></i>${naiveStatus}</span></div><p class="protocol-note">${naiveState}${naive.host?` · ${esc(naive.host)}`:''}</p><div class="protocol-access"><span><small>Доступы</small><strong>${naiveCred.available===false?'—':number(naiveCred.active)}</strong></span><span><small>Отключённые</small><strong>${naiveCred.available===false?'—':number(naiveCred.disabled)}</strong></span></div><div class="traffic-unavailable"><span>${icon('transfer')}</span><span><b>↑ ${bytes(naive.traffic?.aggregate?.upload_bytes_decimal)} · ↓ ${bytes(naive.traffic?.aggregate?.download_bytes_decimal)} · Σ ${bytes(naive.traffic?.aggregate?.total_bytes_decimal)}</b><small>Только закрытые CONNECT-туннели; активные появятся после закрытия</small></span></div><small class="protocol-caption">${naiveAccess}</small></article>
  </div><div class="dashboard-grid">
    <section class="panel-card"><div class="panel-head"><h2>Состояние сервисов</h2><span>обновлено сейчас</span></div><div class="service-list"><div class="service-row ${mtReady?'':'degraded'}"><i></i><span><b>MTProxy · Telemt</b><small>${mtReady?'Control API отвечает':'Проверьте Telemt'}</small></span><em>${mt.status||'degraded'}</em></div><div class="service-row ${naiveReady||!naiveAvailable?'':'degraded'}"><i></i><span><b>NaiveProxy · manager</b><small>${naiveState}</small></span><em>${naive.status}</em></div><div class="service-row ${location.protocol==='https:'?'':'degraded'}"><i></i><span><b>Proxy Control</b><small>${location.protocol==='https:'?'HTTPS · защищённое соединение':'HTTP · соединение не защищено'}</small></span><em>${location.protocol==='https:'?'secure':'insecure'}</em></div></div></section>
    <section class="panel-card"><div class="panel-head"><h2>Быстрые действия</h2><span>по протоколам</span></div><div class="quick-actions">${state.me.role!=='viewer'?`<button class="quick-action" data-quick="mieru-users"><span>${icon('manage')}</span><span><b>Открыть Mieru</b><small>rolling quotas и application bytes</small></span></button><button class="quick-action" data-quick="mt-add"><span>${icon('plus')}</span><span><b>Новый MTProxy доступ</b><small>Ссылка и QR-код</small></span></button>`:''}<button class="quick-action" data-quick="mt-users"><span>${icon('manage')}</span><span><b>Открыть MTProxy</b><small>Доступы, лимиты и ротация</small></span></button>${naiveAvailable?`${state.me.role!=='viewer'?`<button class="quick-action" data-quick="naive-add"><span>${icon('plus')}</span><span><b>Новый NaiveProxy доступ</b><small>HTTPS-конфигурация</small></span></button>`:''}<button class="quick-action" data-quick="naive-users"><span>${icon('manage')}</span><span><b>Открыть NaiveProxy</b><small>Статусы и конфигурации</small></span></button>`:''}<button class="quick-action" data-quick="refresh"><span>${icon('refresh')}</span><span><b>Обновить состояние</b><small>Получить свежую статистику</small></span></button></div></section>
  </div>`;
}

function filteredUsers(){const q=state.query.toLowerCase();return state.users.filter(user=>(state.filter==='all'||(state.filter==='active'&&user.enabled!==false)||(state.filter==='blocked'&&user.enabled===false))&&String(user.username).toLowerCase().includes(q))}
function userUsage(user){const quota=Number(user.data_quota_bytes)||0;if(!quota)return 'Без квоты';const used=Number(user.quota_used_bytes)||0;return `${bytes(used)} / ${bytes(quota)}`}
function userRow(user){const enabled=user.enabled!==false;const connections=user.current_connections??user.active_connections??0;return `<div class="data-row" data-name="${esc(user.username)}"><div class="identity"><span class="user-glyph">${esc(initials(user.username))}</span><span><b>${esc(user.username)}</b><small>MTProto · FakeTLS</small></span></div><div class="cell"><span class="status-pill ${enabled?'active':'blocked'}"><i></i>${enabled?'Активен':'Заблокирован'}</span></div><div class="cell"><b>${userUsage(user)}</b><small>${number(connections)} соединений</small></div><div class="row-actions">${state.me.role!=='viewer'?`<button class="action-button" data-action="limits" data-user="${esc(user.username)}">Лимиты</button><button class="action-button share" data-action="share" data-user="${esc(user.username)}">QR и ссылка</button><button class="action-button" data-action="${enabled?'disable':'enable'}" data-user="${esc(user.username)}">${enabled?'Блокировать':'Разблокировать'}</button><button class="action-button" data-action="rotate" data-user="${esc(user.username)}">Новый ключ</button><button class="action-button danger-text" data-action="delete" data-user="${esc(user.username)}">Удалить</button>`:'<span class="cell">Только просмотр</span>'}</div></div>`}
function paintUsers(){const items=filteredUsers();const container=document.querySelector('#user-list');if(!container)return;container.innerHTML=items.length?items.map(userRow).join(''):`<div class="empty-state"><span>◇</span><h3>Подключений не найдено</h3><p>Измените поиск или создайте новый доступ.</p></div>`}
async function renderUsers(generation=navigationGeneration){
  const users=await refreshUsers(generation);if(generation!==navigationGeneration||state.view!=='users'||users===null)return;view.innerHTML=`<div class="toolbar"><div class="search"><input id="user-search" type="search" value="${esc(state.query)}" placeholder="Поиск по имени" aria-label="Поиск пользователей"></div><div class="filter-pills"><button class="filter-pill ${state.filter==='all'?'active':''}" data-filter="all">Все · ${state.users.length}</button><button class="filter-pill ${state.filter==='active'?'active':''}" data-filter="active">Активные</button><button class="filter-pill ${state.filter==='blocked'?'active':''}" data-filter="blocked">Заблокированные</button></div></div><section class="data-panel"><div class="data-head"><span>Пользователь</span><span>Статус</span><span>Квота (после сброса)</span><span class="align-right">Действия</span></div><div id="user-list"></div></section>`;paintUsers();
}

async function refreshMieru(generation=null){const data=await api('/api/mieru/users');if(generation!==null&&generation!==navigationGeneration)return null;state.mieruUsers=data.items||[];state.mieruService=data.service||{};document.querySelector('#mieru-count').textContent=state.mieruUsers.length;return state.mieruUsers}
function mieruRow(user){const enabled=user.enabled===true,traffic=user.traffic_available===true?`<b>↑ ${bytes(user.upload_bytes)} · ↓ ${bytes(user.download_bytes)}</b><small>application bytes · rolling quota approximate</small>`:'<b>Недоступно</b><small>mita v3.35 не предоставляет типизированную историю трафика</small>';return `<div class="data-row naive-grid"><div class="identity"><span class="user-glyph">${esc(initials(user.username))}</span><span><b>${esc(user.username)}</b><small>Mieru · native AEAD</small></span></div><div class="cell"><span class="status-pill ${enabled?'active':'blocked'}"><i></i>${enabled?'Активен':'Отключён'}</span></div><div class="cell">${traffic}</div><div class="row-actions">${state.me.role!=='viewer'?`<button class="action-button" data-mieru-action="${enabled?'disable':'enable'}" data-user="${esc(user.username)}">${enabled?'Отключить':'Включить'}</button><button class="action-button" data-mieru-action="rotate" data-user="${esc(user.username)}">Новая ссылка + QR</button><button class="action-button danger-text" data-mieru-action="delete" data-user="${esc(user.username)}">Удалить</button>`:'Только просмотр'}</div></div>`}
async function renderMieru(generation=navigationGeneration){const users=await refreshMieru(generation);if(generation!==navigationGeneration||state.view!=='mieru'||users===null)return;const ready=state.mieruService.ready===true;view.innerHTML=`<div class="security-note">Квоты Mieru — rolling application-byte admission quota (approximate): проверяются при открытии сессии и не являются hard cap.</div><div class="naive-overview"><article><small>mita v3.35</small><strong>${ready?'RUNNING':'DEGRADED'}</strong><span class="status-pill ${ready?'active':'blocked'}"><i></i>${ready?'Ready':'Ошибка'}</span></article><article><small>Пользователи</small><strong>${number(users.length)}</strong><span>revision ${esc(state.mieruService.revision||'—')}</span></article></div><section class="data-panel"><div class="data-head naive-grid"><span>Пользователь</span><span>Статус</span><span>Трафик</span><span class="align-right">Действия</span></div>${users.length?users.map(mieruRow).join(''):'<div class="empty-state"><h3>Mieru-доступов нет</h3></div>'}</section>`}
async function mieruAction(action,username,button){try{const revision=state.mieruService.revision;if(!await confirmed('Изменить Mieru-доступ?',`${action} для ${username}. Ротация и отзыв принудительно перезапускают mita.`,`Продолжить`))return;setBusy(button,true);let data;if(action==='delete')data=await api(`/api/mieru/users/${encodeURIComponent(username)}`,{method:'DELETE',body:JSON.stringify({expected_revision:revision})});else data=await api(`/api/mieru/users/${encodeURIComponent(username)}/${action}`,{method:'POST',body:JSON.stringify({expected_revision:revision})});if(action==='rotate')await revealMieruToken(data.reveal_token,username);toast('Mieru-доступ обновлён');await renderMieru()}catch(e){toast(e.message,'error')}finally{setBusy(button,false)}}
function shellQuote(value){return `'${String(value).replaceAll("'","'\"'\"'")}'`}
function showMieruAccess(data,username){const link=String(data.share_url||''),qr=qrSource(data.qr);if(!link.startsWith('mierus://')||link.length>4096)throw new Error('Некорректная Mieru-ссылка');document.querySelector('#mieru-access-title').textContent=`Mieru · ${username}`;document.querySelector('#mieru-share-url').value=link;document.querySelector('#mieru-import-command').value=`mieru import config ${shellQuote(link)}`;document.querySelector('#mieru-qr-image').src=qr;document.querySelector('#download-mieru-qr').href=qr;document.querySelector('#download-mieru-qr').download=`mieru-${username}.svg`;document.querySelector('#mieru-access-modal').showModal()}
async function revealMieruToken(token,username){showMieruAccess(await api('/api/reveal/'+encodeURIComponent(token)),username)}

async function refreshNaive(generation=null){const data=await api('/api/naive/users');if(generation!==null&&generation!==navigationGeneration)return null;state.naiveUsers=data.items||[];state.naiveService=data.service||{ready:false,host:''};document.querySelector('#naive-count').textContent=state.naiveUsers.length;return state.naiveUsers}
function filteredNaive(){const q=state.naiveQuery.toLowerCase();return state.naiveUsers.filter(user=>(state.naiveFilter==='all'||(state.naiveFilter==='active'&&user.enabled)||(state.naiveFilter==='blocked'&&!user.enabled))&&String(user.username).toLowerCase().includes(q))}
function naiveRow(user){const enabled=user.enabled===true;return `<div class="data-row naive-grid" data-naive-name="${esc(user.username)}"><div class="identity"><span class="user-glyph naive-glyph">${esc(initials(user.username))}</span><span><b>${esc(user.username)}</b><small>HTTPS · HTTP/2 CONNECT</small></span></div><div class="cell"><span class="status-pill ${enabled?'active':'blocked'}"><i></i>${enabled?'Активен':'Отключён'}</span></div><div class="cell"><b>↑ ${bytes(user.upload_bytes_decimal)} · ↓ ${bytes(user.download_bytes_decimal)} · Σ ${bytes(user.total_bytes_decimal)}</b><small>с ${date(user.period_start)}</small></div><div class="row-actions">${state.me.role!=='viewer'?`<button class="action-button share" data-naive-action="access" data-user="${esc(user.username)}">Конфигурация</button><button class="action-button" data-naive-action="reset-traffic" data-user="${esc(user.username)}">Сбросить трафик</button><button class="action-button" data-naive-action="${enabled?'disable':'enable'}" data-user="${esc(user.username)}">${enabled?'Отключить':'Включить'}</button><button class="action-button" data-naive-action="rotate" data-user="${esc(user.username)}">Новый пароль</button><button class="action-button danger-text" data-naive-action="delete" data-user="${esc(user.username)}">Удалить</button>`:'<span class="cell">Только просмотр</span>'}</div></div>`}
function paintNaive(){const container=document.querySelector('#naive-list');if(!container)return;const items=filteredNaive();container.innerHTML=items.length?items.map(naiveRow).join(''):`<div class="empty-state"><span>◇</span><h3>Naive-доступы не найдены</h3><p>Измените поиск или создайте новый доступ.</p></div>`}
async function renderNaive(generation=navigationGeneration){
  const users=await refreshNaive(generation);if(generation!==navigationGeneration||state.view!=='naive'||users===null)return;const active=users.filter(x=>x.enabled).length,blocked=users.length-active,ready=state.naiveService.ready===true;
  view.innerHTML=`<div class="naive-overview"><article><span class="naive-mark">${icon('status')}</span><div><small>Сервис</small><b>${ready?'Caddy работает':'Manager недоступен'}</b><em>${esc(state.naiveService.host||'—')}</em></div><span class="status-pill ${ready?'active':'blocked'}"><i></i>${ready?'Ready':'Ошибка'}</span></article><article><small>Доступы</small><strong>${number(active)}</strong><span>${blocked?`${blocked} отключено`:'Все активны'}</span></article><article><small>Учёт</small><strong>${bytes(sumNaiveTraffic(users))}</strong><span>payload-байты закрытых CONNECT</span></article></div><div class="toolbar"><div class="search"><input id="naive-search" type="search" value="${esc(state.naiveQuery)}" placeholder="Поиск Naive-доступа" aria-label="Поиск NaiveProxy пользователей"></div><div class="filter-pills"><button class="filter-pill ${state.naiveFilter==='all'?'active':''}" data-naive-filter="all">Все · ${users.length}</button><button class="filter-pill ${state.naiveFilter==='active'?'active':''}" data-naive-filter="active">Активные</button><button class="filter-pill ${state.naiveFilter==='blocked'?'active':''}" data-naive-filter="blocked">Отключённые</button></div></div><section class="data-panel"><div class="data-head naive-grid"><span>Доступ</span><span>Статус</span><span>Трафик ↑ / ↓ / Σ</span><span class="align-right">Действия</span></div><div id="naive-list"></div></section>`;paintNaive();
}

async function renderFleet(generation=navigationGeneration){
  const data=await api('/api/fleet/nodes');if(generation!==navigationGeneration||state.view!=='fleet')return;state.fleet=data.items||[];document.querySelector('#fleet-count').textContent=state.fleet.length;
  view.innerHTML=`<div class="security-note">Узлы подключаются исходящим mTLS long-poll. Идентичность привязана к SAN, серийному номеру и отпечатку сертификата; bearer fallback отсутствует.</div><section class="data-panel"><div class="data-head admin-grid"><span>Узел</span><span>Telemt</span><span>Очередь</span><span class="align-right">Транспорт</span></div>${state.fleet.length?state.fleet.map(node=>`<div class="data-row admin-grid"><div class="identity"><span class="user-glyph">${esc(initials(node.node_id))}</span><span><b>${esc(node.display_name)}</b><small>${esc(node.node_id)} · ${esc(node.inventory?.region||'регион не задан')}</small></span></div><div class="cell"><b>${esc(node.inventory?.telemt_version||'—')}</b><small>${esc(node.inventory?.agent_version||'агент не подключён')}</small></div><div class="cell"><b>${number(Math.max(0,(node.next_sequence||1)-1-(node.last_result_sequence||0)))}</b><small>подготовлено</small></div><div class="row-actions"><span class="status-pill ${node.auth_state==='connected'?'active':'blocked'}"><i></i>${esc(node.auth_state)}</span></div></div>`).join(''):'<div class="empty-state"><span>◇</span><h3>Узлы не зарегистрированы</h3><p>Владелец может добавить обезличенный inventory через Fleet API.</p></div>'}</section>`;
}

async function renderAdmins(generation=navigationGeneration){
  const data=await api('/api/admins');if(generation!==navigationGeneration||state.view!=='admins')return;state.admins=data.items||[];const activeOwners=state.admins.filter(x=>x.role==='owner'&&x.active).length;view.innerHTML=`<section class="data-panel"><div class="data-head admin-grid"><span>Администратор</span><span>Роль</span><span>Статус</span><span class="align-right">Действия</span></div>${state.admins.map(admin=>{const lastOwner=admin.role==='owner'&&admin.active&&activeOwners===1;return `<div class="data-row admin-grid"><div class="identity"><span class="user-glyph">${esc(initials(admin.username))}</span><span><b>${esc(admin.username)}</b><small>Создан ${date(admin.created_at)}</small></span></div><div class="cell">${esc(roleNames[admin.role]||admin.role)}</div><div class="cell"><span class="status-pill ${admin.active?'active':'blocked'}"><i></i>${admin.active?'Активен':'Отключён'}</span></div><div class="row-actions"><button class="action-button" data-action="edit-admin" data-id="${admin.id}">Настроить</button><button class="action-button" data-action="toggle-admin" data-id="${admin.id}" ${lastOwner?'disabled title="Последнего владельца нельзя отключить"':''}>${admin.active?'Отключить':'Включить'}</button></div></div>`}).join('')}</section>`;
}
async function renderAudit(generation=navigationGeneration){const data=await api('/api/audit');if(generation!==navigationGeneration||state.view!=='audit')return;state.audit=data.items||[];view.innerHTML=`<section class="data-panel"><div class="audit-list">${state.audit.length?state.audit.map(item=>`<div class="audit-row"><span>${date(item.happened_at)}</span><span>${esc(item.actor_username||'system')}</span><span class="audit-action">${esc(actionNames[item.action]||item.action)}</span><span>${esc(item.target||'—')}</span></div>`).join(''):'<div class="empty-state"><span>≡</span><h3>Журнал пока пуст</h3><p>Здесь появятся действия администраторов.</p></div>'}</div></section>`}

function syncCreateButton(){const input=document.querySelector('#new-user'),button=document.querySelector('#create-user');button.disabled=!input.value||!input.checkValidity()}
function openUserModal(){document.querySelector('#user-form').reset();document.querySelector('#user-error').textContent='';syncCreateButton();document.querySelector('#user-modal').showModal();setTimeout(()=>document.querySelector('#new-user').focus(),50)}
function localDateTime(value){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.valueOf()))return '';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)}
function openLimitsModal(user){const form=document.querySelector('#limits-form');form.reset();document.querySelector('#limits-user').value=user.username;document.querySelector('#limits-title').textContent=`Лимиты · ${user.username}`;document.querySelector('#limit-quota').value=user.data_quota_bytes?user.data_quota_bytes/1073741824:'';document.querySelector('#limit-up').value=user.rate_limit_up_bps?user.rate_limit_up_bps/1000000:'';document.querySelector('#limit-down').value=user.rate_limit_down_bps?user.rate_limit_down_bps/1000000:'';document.querySelector('#limit-connections').value=user.max_tcp_conns??'';document.querySelector('#limit-ips').value=user.max_unique_ips??'';document.querySelector('#limit-expiration').value=localDateTime(user.expiration_rfc3339);document.querySelector('#limits-error').textContent='';document.querySelector('#limits-modal').showModal()}
function optionalNumber(id,multiplier=1){const value=document.querySelector(id).value;return value===''?null:Math.round(Number(value)*multiplier)}
function syncNaiveCreateButton(){const input=document.querySelector('#new-naive-user'),button=document.querySelector('#create-naive');button.disabled=!input.value||!input.checkValidity()}
function syncMieruCreateButton(){const form=document.querySelector('#mieru-form'),button=document.querySelector('#create-mieru');button.disabled=!form.checkValidity()}
function openMieruModal(){const form=document.querySelector('#mieru-form');form.reset();document.querySelector('#mieru-error').textContent='';syncMieruCreateButton();document.querySelector('#mieru-modal').showModal()}
function openNaiveModal(){document.querySelector('#naive-form').reset();document.querySelector('#naive-error').textContent='';syncNaiveCreateButton();document.querySelector('#naive-modal').showModal();setTimeout(()=>document.querySelector('#new-naive-user').focus(),50)}
function openFleetModal(){document.querySelector('#fleet-form').reset();document.querySelector('#fleet-error').textContent='';document.querySelector('#fleet-modal').showModal();setTimeout(()=>document.querySelector('#new-node-id').focus(),50)}
async function createFleetNode(button){const form=document.querySelector('#fleet-form'),error=document.querySelector('#fleet-error');if(!form.reportValidity())return;const nodeId=document.querySelector('#new-node-id').value,displayName=document.querySelector('#new-node-name').value.trim(),region=document.querySelector('#new-node-region').value.trim(),inventory={};if(region)inventory.region=region;error.textContent='';try{setBusy(button,true,'Добавляем…');await api('/api/fleet/nodes',{method:'POST',body:JSON.stringify({node_id:nodeId,display_name:displayName,inventory})});document.querySelector('#fleet-modal').close();toast('Узел добавлен в реестр');await renderFleet()}catch(e){error.textContent=e.message}finally{setBusy(button,false)}}
function openAdminModal(admin=null){const lastOwner=admin?.role==='owner'&&admin?.active&&state.admins.filter(x=>x.role==='owner'&&x.active).length===1;document.querySelector('#admin-form').reset();document.querySelector('#admin-id').value=admin?.id||'';document.querySelector('#admin-user').value=admin?.username||'';document.querySelector('#admin-user').disabled=Boolean(admin);document.querySelector('#admin-role').value=admin?.role||'viewer';document.querySelector('#admin-role').disabled=lastOwner;document.querySelector('#admin-modal-title').textContent=admin?'Настроить администратора':'Новый администратор';document.querySelector('#password-hint').textContent=admin?'Оставьте пустым, чтобы не менять':'Обязателен для нового администратора';document.querySelector('#delete-admin').hidden=!admin||lastOwner;document.querySelector('#admin-error').textContent=lastOwner?'Последнего активного владельца нельзя отключить, понизить или удалить.':'';document.querySelector('#admin-modal').showModal()}
function confirmed(title,text,button='Продолжить'){const dialog=document.querySelector('#confirm');document.querySelector('#confirm-title').textContent=title;document.querySelector('#confirm-text').textContent=text;document.querySelector('#confirm-ok').textContent=button;dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='default'),{once:true}))}
function showAccess(data,username){const link=proxyLink(data.link),qr=qrSource(data.qr);document.querySelector('#access-title').textContent=`Доступ · ${username}`;document.querySelector('#access-link').value=link;document.querySelector('#qr-image').src=qr;document.querySelector('#open-telegram').href=link;document.querySelector('#download-qr').href=qr;document.querySelector('#download-qr').download=`mtproxy-${username}.svg`;document.querySelector('#access-modal').showModal()}
async function revealToken(token,username){const data=await api('/api/reveal/'+encodeURIComponent(token));showAccess(data,username)}
function showNaiveAccess(data,username){const url=naiveProxyUrl(data.proxy_url,username),qr=qrSource(data.qr);naiveConfigText=JSON.stringify({listen:'socks://127.0.0.1:1080',proxy:url},null,2);if(naiveConfigUrl)URL.revokeObjectURL(naiveConfigUrl);naiveConfigUrl=URL.createObjectURL(new Blob([naiveConfigText+'\n'],{type:'application/json'}));document.querySelector('#naive-access-title').textContent=`NaiveProxy · ${username}`;document.querySelector('#naive-proxy-url').value=url;document.querySelector('#naive-qr-image').src=qr;const download=document.querySelector('#download-naive-config');download.href=naiveConfigUrl;download.download=`naive-${username}.json`;document.querySelector('#naive-access-modal').showModal()}
async function revealNaiveToken(token,username){const data=await api('/api/reveal/'+encodeURIComponent(token));showNaiveAccess(data,username)}

async function userAction(action,username,button){
  try{
    if(action==='limits'){const user=state.users.find(item=>item.username===username);if(user)openLimitsModal(user);return}
    if(action==='share'){setBusy(button,true,'Загрузка…');const data=await api(`/api/users/${encodeURIComponent(username)}/access`,{method:'POST'});showAccess(data,username);return}
    if(action==='disable'&&!await confirmed('Заблокировать доступ?',`${username} будет отключён, активные соединения будут закрыты.`,`Заблокировать`))return;
    if(action==='enable'&&!await confirmed('Разблокировать доступ?',`${username} снова сможет подключаться к прокси.`,`Разблокировать`))return;
    if(action==='rotate'&&!await confirmed('Создать новый ключ?',`Старая ссылка ${username} перестанет работать. Сохраните новый QR-код после ротации.`,`Обновить ключ`))return;
    if(action==='delete'&&!await confirmed('Удалить подключение?',`${username} будет удалён без возможности восстановления.`,`Удалить`))return;
    setBusy(button,true);
    if(action==='delete')await api(`/api/users/${encodeURIComponent(username)}`,{method:'DELETE'});else{const data=await api(`/api/users/${encodeURIComponent(username)}/${action}`,{method:'POST'});if(action==='rotate')await revealToken(data.reveal_token,username)}
    toast(action==='delete'?'Подключение удалено':action==='disable'?'Доступ заблокирован':action==='enable'?'Доступ разблокирован':'Ключ обновлён');await renderUsers();
  }catch(error){toast(error.message,'error')}finally{setBusy(button,false)}
}

async function naiveAction(action,username,button){
  try{
    if(action==='access'){setBusy(button,true,'Загрузка…');showNaiveAccess(await api(`/api/naive/users/${encodeURIComponent(username)}/access`,{method:'POST'}),username);return}
    if(action==='reset-traffic'&&!await confirmed('Сбросить локальный счётчик?',`Учётные данные ${username} не изменятся. Активные туннели будут учтены после закрытия.`,`Сбросить`))return;
    if(action==='disable'&&!await confirmed('Отключить Naive-доступ?',`${username} больше не сможет подключаться после применения Caddy.`,`Отключить`))return;
    if(action==='enable'&&!await confirmed('Включить Naive-доступ?',`${username} снова сможет использовать HTTPS-прокси.`,`Включить`))return;
    if(action==='rotate'&&!await confirmed('Сменить пароль?',`Текущая конфигурация ${username} немедленно перестанет работать.`,`Сменить пароль`))return;
    if(action==='delete'&&!await confirmed('Удалить Naive-доступ?',`${username} будет удалён без возможности восстановления.`,`Удалить`))return;
    setBusy(button,true);
    if(action==='delete')await api(`/api/naive/users/${encodeURIComponent(username)}`,{method:'DELETE'});else if(action==='reset-traffic')await api(`/api/naive/users/${encodeURIComponent(username)}/traffic/reset`,{method:'POST'});else{const data=await api(`/api/naive/users/${encodeURIComponent(username)}/${action}`,{method:'POST'});if(action==='rotate')await revealNaiveToken(data.reveal_token,username)}
    toast(action==='delete'?'Naive-доступ удалён':action==='disable'?'Naive-доступ отключён':action==='enable'?'Naive-доступ включён':action==='reset-traffic'?'Счётчик Naive-трафика сброшен':'Пароль обновлён');await renderNaive();
  }catch(error){toast(error.message,'error')}finally{setBusy(button,false)}
}

async function init(){
  try{state.me=await api('/api/auth/me');document.querySelector('#profile-name').textContent=state.me.username;document.querySelector('#profile-role').textContent=roleNames[state.me.role]||state.me.role;document.querySelector('#avatar').textContent=initials(state.me.username);document.querySelectorAll('[data-view="naive"]').forEach(x=>x.hidden=state.me.features?.naive!==true);document.querySelectorAll('[data-view="mieru"]').forEach(x=>x.hidden=state.me.features?.mieru!==true);document.querySelectorAll('.owner-only').forEach(x=>x.hidden=state.me.role!=='owner');document.querySelectorAll('.audit-nav').forEach(x=>x.hidden=false);await navigate('dashboard')}catch(error){errorState(error)}
}

if(view){
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.view)));
document.querySelector('#add').addEventListener('click',()=>state.view==='admins'?openAdminModal():state.view==='fleet'?openFleetModal():state.view==='naive'?openNaiveModal():state.view==='mieru'?openMieruModal():openUserModal());
document.querySelector('#refresh').addEventListener('click',event=>{setBusy(event.currentTarget,true,'…');navigate(state.view).finally(()=>setBusy(event.currentTarget,false))});
document.querySelector('#logout').addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST'});location='/login'}catch(error){toast(error.message,'error')}});
document.querySelector('#profile-button').addEventListener('click',()=>toast(`${state.me.username} · ${roleNames[state.me.role]}`));
document.querySelector('#new-user').addEventListener('input',syncCreateButton);
document.querySelector('#create-mieru').addEventListener('click',async event=>{const form=document.querySelector('#mieru-form'),username=document.querySelector('#new-mieru-user').value,days=Number(document.querySelector('#mieru-days').value),megabytes=Number(document.querySelector('#mieru-mib').value),error=document.querySelector('#mieru-error');error.textContent='';if(!form.reportValidity())return;try{setBusy(event.currentTarget,true);const data=await api('/api/mieru/users',{method:'POST',body:JSON.stringify({username,quotas:[{days,megabytes}],expected_revision:state.mieruService.revision})});document.querySelector('#mieru-modal').close();await revealMieruToken(data.reveal_token,username);await renderMieru()}catch(e){error.textContent=e.message}finally{setBusy(event.currentTarget,false);syncMieruCreateButton()}});
document.querySelector('#create-fleet-node').addEventListener('click',event=>createFleetNode(event.currentTarget));
document.querySelector('#new-naive-user').addEventListener('input',syncNaiveCreateButton);
document.querySelector('#mieru-form').addEventListener('input',syncMieruCreateButton);
document.querySelector('#create-user').addEventListener('click',async event=>{const input=document.querySelector('#new-user'),error=document.querySelector('#user-error');error.textContent='';if(!input.reportValidity())return;try{setBusy(event.currentTarget,true,'Создаём…');const data=await api('/api/users',{method:'POST',body:JSON.stringify({username:input.value})});document.querySelector('#user-modal').close();await revealToken(data.reveal_token,input.value);toast('Доступ создан');await refreshUsers();paintUsers()}catch(e){error.textContent=e.message}finally{setBusy(event.currentTarget,false)}});
document.querySelector('#save-limits').addEventListener('click',async event=>{const form=document.querySelector('#limits-form'),error=document.querySelector('#limits-error'),username=document.querySelector('#limits-user').value;if(!form.reportValidity())return;const expiration=document.querySelector('#limit-expiration').value;const payload={data_quota_bytes:optionalNumber('#limit-quota',1073741824),rate_limit_up_bps:optionalNumber('#limit-up',1000000),rate_limit_down_bps:optionalNumber('#limit-down',1000000),max_tcp_conns:optionalNumber('#limit-connections'),max_unique_ips:optionalNumber('#limit-ips'),expiration_rfc3339:expiration?new Date(expiration).toISOString():null};error.textContent='';try{setBusy(event.currentTarget,true);await api(`/api/users/${encodeURIComponent(username)}/limits`,{method:'POST',body:JSON.stringify(payload)});document.querySelector('#limits-modal').close();toast('Ограничения сохранены');await renderUsers()}catch(e){error.textContent=e.message}finally{setBusy(event.currentTarget,false)}});
document.querySelector('#reset-quota').addEventListener('click',async event=>{const username=document.querySelector('#limits-user').value;if(!await confirmed('Сбросить счётчик трафика?',`Накопленный расход ${username} станет равен нулю. Сам лимит сохранится.`,`Сбросить`))return;try{setBusy(event.currentTarget,true);await api(`/api/users/${encodeURIComponent(username)}/reset-quota`,{method:'POST'});document.querySelector('#limits-modal').close();toast('Счётчик трафика сброшен');await renderUsers()}catch(e){document.querySelector('#limits-error').textContent=e.message}finally{setBusy(event.currentTarget,false)}});
document.querySelector('#create-naive').addEventListener('click',async event=>{const input=document.querySelector('#new-naive-user'),error=document.querySelector('#naive-error'),username=input.value;error.textContent='';if(!input.reportValidity())return;try{setBusy(event.currentTarget,true,'Применяем…');const data=await api('/api/naive/users',{method:'POST',body:JSON.stringify({username})});document.querySelector('#naive-modal').close();await revealNaiveToken(data.reveal_token,username);toast('Naive-доступ создан');await refreshNaive();paintNaive()}catch(e){error.textContent=e.message}finally{setBusy(event.currentTarget,false)}});
document.querySelector('#save-admin').addEventListener('click',async event=>{const form=document.querySelector('#admin-form');if(!form.reportValidity())return;const id=document.querySelector('#admin-id').value,password=document.querySelector('#admin-password').value,error=document.querySelector('#admin-error');error.textContent='';const payload={role:document.querySelector('#admin-role').value};if(password)payload.password=password;if(!id){payload.username=document.querySelector('#admin-user').value;payload.password=password}if(!id&&password.length<12){error.textContent='Пароль должен содержать не менее 12 символов';return}try{setBusy(event.currentTarget,true);await api(id?`/api/admins/${id}`:'/api/admins',{method:id?'PATCH':'POST',body:JSON.stringify(payload)});document.querySelector('#admin-modal').close();toast('Администратор сохранён');await renderAdmins()}catch(e){error.textContent=e.message}finally{setBusy(event.currentTarget,false)}});
document.querySelector('#delete-admin').addEventListener('click',async()=>{const id=document.querySelector('#admin-id').value,admin=state.admins.find(x=>String(x.id)===id);if(!admin||!await confirmed('Удалить администратора?',`${admin.username} потеряет доступ к панели.`,`Удалить`))return;try{await api(`/api/admins/${id}`,{method:'DELETE'});document.querySelector('#admin-modal').close();toast('Администратор удалён');await renderAdmins()}catch(e){toast(e.message,'error')}});
document.querySelector('#copy-link').addEventListener('click',async()=>{const input=document.querySelector('#access-link');try{await navigator.clipboard.writeText(input.value)}catch{input.select();document.execCommand('copy')}toast('Ссылка скопирована')});
document.querySelector('#access-modal').addEventListener('close',()=>{document.querySelector('#access-link').value='';document.querySelector('#qr-image').removeAttribute('src');document.querySelector('#open-telegram').removeAttribute('href');document.querySelector('#download-qr').removeAttribute('href')});
document.querySelector('#copy-mieru-url').addEventListener('click',async()=>{const input=document.querySelector('#mieru-share-url');try{await navigator.clipboard.writeText(input.value)}catch{input.select();document.execCommand('copy')}toast('Mieru-ссылка скопирована')});
document.querySelector('#copy-mieru-command').addEventListener('click',async()=>{const input=document.querySelector('#mieru-import-command');try{await navigator.clipboard.writeText(input.value)}catch{input.select();document.execCommand('copy')}toast('Команда импорта скопирована')});
document.querySelector('#mieru-access-modal').addEventListener('close',()=>{document.querySelector('#mieru-share-url').value='';document.querySelector('#mieru-import-command').value='';document.querySelector('#mieru-qr-image').removeAttribute('src');document.querySelector('#download-mieru-qr').removeAttribute('href')});
document.querySelector('#copy-naive-url').addEventListener('click',async()=>{const input=document.querySelector('#naive-proxy-url');try{await navigator.clipboard.writeText(input.value)}catch{input.select();document.execCommand('copy')}toast('NaiveProxy URL скопирован')});
document.querySelector('#copy-naive-config').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(naiveConfigText)}catch{const input=document.querySelector('#naive-proxy-url');input.select();document.execCommand('copy')}toast('config.json скопирован')});
document.querySelector('#naive-access-modal').addEventListener('close',()=>{document.querySelector('#naive-proxy-url').value='';document.querySelector('#naive-qr-image').removeAttribute('src');document.querySelector('#download-naive-config').removeAttribute('href');if(naiveConfigUrl)URL.revokeObjectURL(naiveConfigUrl);naiveConfigUrl='';naiveConfigText=''});

document.querySelector('#view').addEventListener('input',event=>{if(event.target.id==='user-search'){state.query=event.target.value;paintUsers()}if(event.target.id==='naive-search'){state.naiveQuery=event.target.value;paintNaive()}});
document.querySelector('#view').addEventListener('click',async event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.dataset.filter){state.filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===button));paintUsers();return}
  if(button.dataset.naiveFilter){state.naiveFilter=button.dataset.naiveFilter;document.querySelectorAll('[data-naive-filter]').forEach(x=>x.classList.toggle('active',x===button));paintNaive();return}
  if(button.dataset.action==='retry'){navigate(state.view);return}
  if(button.dataset.mieruAction&&button.dataset.user){await mieruAction(button.dataset.mieruAction,button.dataset.user,button);return}
  if(button.dataset.naiveAction&&button.dataset.user){await naiveAction(button.dataset.naiveAction,button.dataset.user,button);return}
  if(button.dataset.action&&button.dataset.user){await userAction(button.dataset.action,button.dataset.user,button);return}
  if(button.dataset.action==='edit-admin'){openAdminModal(state.admins.find(x=>String(x.id)===button.dataset.id));return}
  if(button.dataset.action==='toggle-admin'){const admin=state.admins.find(x=>String(x.id)===button.dataset.id);if(!admin||button.disabled||!await confirmed(admin.active?'Отключить администратора?':'Включить администратора?',admin.active?`${admin.username} потеряет доступ, активные сессии будут закрыты.`:`${admin.username} снова сможет войти в панель.`,admin.active?'Отключить':'Включить'))return;try{setBusy(button,true);await api(`/api/admins/${admin.id}`,{method:'PATCH',body:JSON.stringify({active:!admin.active})});toast(admin.active?'Администратор отключён':'Администратор включён');await renderAdmins()}catch(e){toast(e.message,'error')}finally{setBusy(button,false)}return}
  if(button.dataset.quick==='mieru-users'){navigate('mieru');return}if(button.dataset.quick==='mt-add'){openUserModal();return}if(button.dataset.quick==='mt-users'){navigate('users');return}if(button.dataset.quick==='naive-add'){openNaiveModal();return}if(button.dataset.quick==='naive-users'){navigate('naive');return}if(button.dataset.quick==='refresh'){navigate('dashboard')}
});

init();
}

document.querySelector('#mobile-logout')?.addEventListener('click',()=>document.querySelector('#logout').click());
const transport=document.querySelector('#transport-state');if(transport){const secure=location.protocol==='https:';transport.classList.toggle('degraded',!secure);transport.lastChild.textContent=secure?' Защищённое HTTPS-соединение':' HTTP-соединение не защищено'}
